pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256[] memory v) public {
        // Ensure arrays have same length and are non-empty (domain constraint from the contract)
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);
        // Avoid precompile collisions and restrict caddress to EOAs / contracts that will succeed
        // (the reference only succeeds when all calls succeed; domain must be admissible for the reference)
        vm.assume(caddress != address(this));
        vm.assume(caddress != address(c));
        vm.assume(caddress != address(0));
        // Also avoid addresses that might break the assumption that external call always succeeds:
        // We need a helper that always succeeds to test return value, not revert.
        // Deploy SuccessReturner helper that returns true on transferFrom.
        SuccessReturner helper = new SuccessReturner();
        caddress = address(helper);

        // Now drive the call
        bool success;
        bytes memory ret;
        (success, ret) = caddress.call(abi.encodeWithSignature("transfer(address,address,address[],uint256[])", from, caddress, _tos, v));
        // Since we used a helper that succeeds, the call must succeed
        vm.assume(success);

        // Assertion: the returned value must be true
        bool returned = abi.decode(ret, (bool));
        assertTrue(returned);
    }
}

// Adversarial helper: low-level call always succeeds because EOA would succeed,
// but we need a contract that returns true to match transferFrom selector.
contract SuccessReturner {
    fallback() external payable returns (bytes memory) {
        // Match the transferFrom selector and return true
        // The reference calls transferFrom(address,address,uint256) and requires it returns true.
        // We just return true encoded as bool.
        return abi.encode(true);
    }
}

